	for i := range a {
		a[i] = readInt()
		prefix[i+1] = prefix[i] + a[i]
	}
	out := make([]byte, 0, 16*q)
	for t := 0; t < q; t++ {
		ends := [3]int{readInt(), readInt(), n}
		total, start := 0, 0
		for _, end := range ends {
			total += (end-start)*a[end-1] - (prefix[end] - prefix[start])
			start = end
		}
		out = strconv.AppendInt(out, int64(total), 10)
		if t+1 < q {
			out = append(out, ' ')
		} else {
			out = append(out, '\n')
		}
	}
	os.Stdout.Write(out)
}

